        if (processingRef.current || !baselineRef.current) return;
        const current = drawFrame(); if (!current) return; smallCtx.drawImage(current.canvas, 0, 0, 64, 48); const pixels = smallCtx.getImageData(0, 0, 64, 48).data; const base = baselineRef.current.data; let changed = 0;
        for (let index = 0; index < pixels.length; index += 4) { const delta = Math.abs(pixels[index] - base[index]) + Math.abs(pixels[index + 1] - base[index + 1]) + Math.abs(pixels[index + 2] - base[index + 2]); if (delta > 75) changed++; }
        const changeRatio = changed / (pixels.length / 4);
        if (awaitingClearRef.current) {
          if (changeRatio < 0.03) { if (!backgroundSinceRef.current) backgroundSinceRef.current = Date.now(); if (Date.now() - backgroundSinceRef.current >= 1000) { awaitingClearRef.current = false; awaitingReviewRef.current = false; candidateSinceRef.current = 0; setCameraMessage('Background clear. Place the next object inside the focus frame.'); } } else backgroundSinceRef.current = 0;
          return;
        }
        if (awaitingReviewRef.current) return;
